package org.primefaces.util;

import java.io.Serializable;
import java.math.BigDecimal;
import java.text.DecimalFormat;
import java.text.ParsePosition;

/**
 * <p>
 * <b>BigDecimal Validation</b> and Conversion routines.
 * </p>
 * <p>
 * This validator is used to parse numeric strings into BigDecimal values.
 * </p>
 */
public class BigDecimalValidator implements Serializable {

    private static final long serialVersionUID = 1L;

    private static final BigDecimalValidator VALIDATOR = new BigDecimalValidator();

    /**
     * Return a singleton instance of this validator.
     *
     * @return A singleton instance of the BigDecimalValidator.
     */
    public static BigDecimalValidator getInstance() {
        return VALIDATOR;
    }

    /**
     * <p>
     * Validate/convert a numeric string using the specified <code>DecimalFormat</code>.
     * </p>
     *
     * @param value The value validation is being performed on.
     * @param format The format to use for the number format.
     * @return The parsed <code>BigDecimal</code> if valid or <code>null</code> if invalid.
     */
    public BigDecimal validate(String value, DecimalFormat format) {
        if (value == null || value.isEmpty()) {
            return null;
        }

        ParsePosition pos = new ParsePosition(0);
        Number parsedValue = format.parse(value, pos);

        if (pos.getErrorIndex() > -1) {
            return null;
        }

        if (pos.getIndex() < value.length()) {
            return null;
        }

        if (parsedValue != null) {
            if (Double.isInfinite(parsedValue.doubleValue())) {
                return null;
            }

            // Convert to BigDecimal
            if (parsedValue instanceof BigDecimal) {
                return (BigDecimal) parsedValue;
            } else if (parsedValue instanceof Long) {
                return BigDecimal.valueOf((Long) parsedValue);
            } else {
                return new BigDecimal(parsedValue.toString());
            }
        }

        return null;
    }
}
